# ALGORITHM_ANALYSIS_NOTE_BEGIN
# Summary: A simple, robust (1+1)-Evolution Strategy with adaptive step-size (1/5th success rule).
# Search state: Maintains a single current best candidate point and a global isotropic mutation strength (sigma).
# Candidate generation: New candidates are generated by adding Gaussian noise scaled by sigma to the current best point.
# Selection and replacement: Simple greedy selection; the candidate replaces the current point if its objective value is lower.
# Adaptation: The mutation strength sigma is updated every 10 iterations: increased if success rate > 0.2, decreased if < 0.2.
# Exploration mechanisms: Gaussian mutation provides continuous exploration; sigma adaptation allows for global-to-local transitions.
# Exploitation mechanisms: Local hill-climbing via greedy updates and step-size shrinkage.
# Boundary handling: candidates are clipped to the provided lower and upper bounds.
# Budget strategy: A strict loop runs until the provided budget is exhausted.
# Closest known influences: (1+1)-ES with 1/5th success rule.
# Novelty or unusual aspects: Minimalist, stateless implementation suitable for black-box environments.
# Failure modes: Can get trapped in sharp local minima; convergence speed slows significantly in very high dimensions.
# ALGORITHM_ANALYSIS_NOTE_END

import numpy as np

class Algorithm:
    def __init__(self, budget, dim):
        self.budget = budget
        self.dim = dim

    def __call__(self, func):
        # Extract bounds
        if hasattr(func, 'bounds'):
            lb, ub = np.array(func.bounds.lb), np.array(func.bounds.ub)
        else:
            lb, ub = np.array(func.lower), np.array(func.upper)
        
        # Initialize
        x = np.random.uniform(lb, ub, self.dim)
        y = func(x)
        budget_left = self.budget - 1
        
        best_x = x.copy()
        best_y = y
        
        # Hyperparameters for (1+1)-ES
        sigma = 0.2 * (ub - lb)
        successes = 0
        iterations = 0
        
        while budget_left > 0:
            # Generate candidate
            candidate = np.clip(best_x + np.random.normal(0, sigma), lb, ub)
            
            # Evaluate
            current_y = func(candidate)
            budget_left -= 1
            iterations += 1
            
            # Selection
            if current_y <= best_y:
                best_x = candidate
                best_y = current_y
                successes += 1
            
            # 1/5th success rule for adaptive sigma
            if iterations == 10:
                if successes / iterations > 0.2:
                    sigma *= 1.22  # Increase step size
                elif successes / iterations < 0.2:
                    sigma /= 1.22  # Decrease step size
                iterations = 0
                successes = 0
                
        return best_x, best_y
